script:
(function () {
  'use strict';
  // Cost of debt: what each debt costs today and until it is paid off, and what that interest
  // would grow to if it were invested instead.
  //   Cost at today's balance: per year = balance x APR, per month = balance x APR / 12,
  //   per day = balance x APR / 365.
  //   Payoff at the current payment: each month interest = balance x APR / 12 (rounded to the
  //   cent) is added, then the fixed payment (capped at what is owed) is paid.
  //   Invested instead: each month's interest charge is treated as a deposit at the end of that
  //   month into an account earning the chosen return, compounded monthly (r / 12), and valued
  //   at the end of the horizon: sum of I_m x (1 + r/12)^(H - m) for months m <= H. Interest
  //   charged after the horizon is not counted.
  // Verified (scratchpad b5debt/math.test.js):
  //   $10,000 at 12% paid $222.45 a month -> 60 months, total interest within $0.10 of the
  //   closed form 60 x 222.4445 - 10,000 = $3,346.67; $10,000 at 0% paid $500 -> 20 months, $0;
  //   per day for $6,200 at 23.99% = $4.08 (6,200 x 0.2399 / 365 = 4.0750);
  //   a single $100 interest charge in month 1 invested at 12% for a 1-year horizon grows to
  //   100 x 1.01^11 = $111.57; a constant $100 a month for 12 months at 0% return = $1,200;
  //   a stream of $100 a month for 12 months at 6% = 100 x ((1.005^12 - 1) / 0.005) = $1,233.56;
  //   a payment at or below the first month's interest is reported by name, never as a result.
  var MAX_MONTHS = 1200;
  var MAX_DEBTS = 10;
  var DEFAULTS = [
    { name: 'Credit card', balance: 6200, apr: 23.99, pay: 200 },
    { name: 'Car loan', balance: 14000, apr: 7.5, pay: 380 },
    { name: 'Student loan', balance: 22000, apr: 5.5, pay: 240 }
  ];
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var monthName = new Intl.DateTimeFormat('en-US', { month: 'short', year: 'numeric' });
  var rowCounter = 0;

  // ---- Calculation ----
  function cents(x) { return Math.round(x * 100) / 100; }

  // debt: { balance, apr (decimal), pay }. Returns the monthly interest charges until paid off.
  function payoff(debt) {
    var bal = debt.balance, charges = [], total = 0, owedByMonth = [];
    for (var m = 1; m <= MAX_MONTHS; m++) {
      var interest = cents(bal * debt.apr / 12);
      bal += interest;
      bal = cents(bal - Math.min(debt.pay, bal));
      charges.push(interest); total += interest; owedByMonth.push(bal);
      if (bal <= 0.005) return { paidOff: true, months: m, interest: total, charges: charges, owed: owedByMonth };
    }
    return { paidOff: false, months: MAX_MONTHS, interest: total, charges: charges, owed: owedByMonth };
  }

  // Value at month `horizon` of interest charges invested at the end of each month.
  function investedValue(charges, annualReturn, horizon) {
    var i = annualReturn / 12, value = 0;
    for (var m = 1; m <= horizon; m++) {
      value = value * (1 + i) + (m <= charges.length ? charges[m - 1] : 0);
    }
    return value;
  }

  function costToday(debt) {
    return { day: debt.balance * debt.apr / 365, month: debt.balance * debt.apr / 12, year: debt.balance * debt.apr };
  }

  // ---- Page ----
  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function dateAfter(months) {
    var now = new Date();
    return monthName.format(new Date(now.getFullYear(), now.getMonth() + months, 1));
  }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }

  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) {
      var td = document.createElement('td');
      td.textContent = text;
      tr.appendChild(td);
    });
    body.appendChild(tr);
  }

  function el(tag, className, text) {
    var e = document.createElement(tag);
    if (className) e.className = className;
    if (text) e.textContent = text;
    return e;
  }

  function numberField(id, label, value, affix, affixFirst, step, max) {
    var wrap = el('div');
    var lab = el('label', 'form-label', label);
    lab.setAttribute('for', id);
    var group = el('div', 'input-group');
    var input = el('input', 'min-w-0 flex-1 bg-transparent px-3 text-[15px] tabular-nums text-ink focus:outline-none');
    input.type = 'number'; input.id = id; input.min = '0'; input.step = step; input.inputMode = 'decimal';
    if (max) input.max = max;
    input.value = value === '' ? '' : String(value);
    var a = el('span', 'input-affix', affix);
    if (affixFirst) { group.appendChild(a); group.appendChild(input); } else { group.appendChild(input); group.appendChild(a); }
    wrap.appendChild(lab); wrap.appendChild(group);
    return wrap;
  }

  function addDebtRow(d) {
    var list = document.getElementById('codDebts');
    rowCounter++;
    var n = rowCounter;
    var row = el('div', 'space-y-3 rounded-xl border border-line p-4');
    row.setAttribute('data-debt-row', String(n));
    var head = el('div', 'flex flex-wrap items-center justify-between gap-2');
    var title = el('p', 'text-sm font-semibold text-ink', 'Debt');
    title.setAttribute('data-debt-title', '');
    var remove = el('button', 'button-secondary h-9 px-3 text-sm', 'Remove');
    remove.type = 'button';
    remove.setAttribute('data-remove', '');
    remove.addEventListener('click', function () {
      if (list.querySelectorAll('[data-debt-row]').length <= 1) return;
      row.remove();
      refreshRows(); update();
    });
    head.appendChild(title); head.appendChild(remove);
    row.appendChild(head);

    var nameWrap = el('div');
    var nameLabel = el('label', 'form-label', 'Name');
    nameLabel.setAttribute('for', 'codName' + n);
    var name = el('input', 'form-control');
    name.type = 'text'; name.id = 'codName' + n; name.maxLength = 40; name.autocomplete = 'off';
    name.placeholder = 'e.g. Visa card';
    name.value = d.name || '';
    nameWrap.appendChild(nameLabel); nameWrap.appendChild(name);
    row.appendChild(nameWrap);

    var pair = el('div', 'form-row form-row-2');
    pair.appendChild(numberField('codBal' + n, 'Balance', d.balance, '$', true, '100'));
    pair.appendChild(numberField('codApr' + n, 'APR', d.apr, '%', false, '0.1', '100'));
    row.appendChild(pair);
    row.appendChild(numberField('codPay' + n, 'Monthly payment', d.pay, '$', true, '10'));
    list.appendChild(row);
    refreshRows();
  }

  function refreshRows() {
    var rows = document.getElementById('codDebts').querySelectorAll('[data-debt-row]');
    rows.forEach(function (row, i) {
      row.querySelector('[data-debt-title]').textContent = 'Debt ' + (i + 1);
      var rm = row.querySelector('[data-remove]');
      rm.disabled = rows.length <= 1;
      rm.setAttribute('aria-label', 'Remove debt ' + (i + 1));
    });
    document.getElementById('codAdd').disabled = rows.length >= MAX_DEBTS;
  }

  function readDebts() {
    var out = [], ok = true;
    var rows = document.getElementById('codDebts').querySelectorAll('[data-debt-row]');
    rows.forEach(function (row, i) {
      var n = row.getAttribute('data-debt-row');
      var name = document.getElementById('codName' + n).value.trim() || ('Debt ' + (i + 1));
      var balEl = document.getElementById('codBal' + n), aprEl = document.getElementById('codApr' + n), payEl = document.getElementById('codPay' + n);
      var bal = parseFloat(balEl.value), apr = aprEl.value.trim() === '' ? 0 : parseFloat(aprEl.value), pay = parseFloat(payEl.value);
      if (balEl.value.trim() === '' || bal === 0) {
        [balEl, aprEl, payEl].forEach(function (e) { e.setAttribute('aria-invalid', 'false'); });
        return;
      }
      var badBal = isNaN(bal) || bal < 0 || bal > 1e8, badApr = isNaN(apr) || apr < 0 || apr > 100, badPay = isNaN(pay) || pay <= 0;
      balEl.setAttribute('aria-invalid', String(badBal));
      aprEl.setAttribute('aria-invalid', String(badApr));
      payEl.setAttribute('aria-invalid', String(badPay));
      if (badBal || badApr || badPay) { ok = false; return; }
      out.push({ name: name, balance: bal, apr: apr / 100, pay: pay });
    });
    return { ok: ok, debts: out };
  }

  function clearResults() {
    ['codDay', 'codMonth', 'codYear', 'codTotal', 'codDate', 'codGrow'].forEach(function (id) { set(id, '–'); });
    set('codGrowNote', ''); set('codDateNote', '');
    document.getElementById('codHorizonNote').hidden = true;
    clearBody('codByDebt'); clearBody('codYears');
  }

  function aprText(apr) { return (apr * 100).toFixed(2).replace(/\.?0+$/, '') + '%'; }

  function update() {
    var error = document.getElementById('codError');
    var ret = parseFloat(document.getElementById('codReturn').value);
    var years = Math.round(parseFloat(document.getElementById('codYearsIn').value));
    var input = readDebts();
    var problem = '';
    if (!input.ok) problem = 'Check the highlighted debts: balances of $0 or more, APRs from 0 to 100% and monthly payments above $0.';
    else if (!input.debts.length) problem = 'Enter at least one debt with a balance above $0.';
    else if (isNaN(ret) || ret < 0 || ret > 30) problem = 'Enter an investment return from 0 to 30%.';
    else if (isNaN(years) || years < 1 || years > 50) problem = 'Enter a growth period of 1 to 50 years.';
    var debts = input.debts, plans = [];
    if (!problem) {
      for (var k = 0; k < debts.length; k++) {
        var p = payoff(debts[k]);
        if (!p.paidOff) {
          problem = 'The payment on ' + debts[k].name + ' does not cover enough of its interest to pay it off within 100 years. Raise that payment.';
          break;
        }
        plans.push(p);
      }
    }
    if (problem) { error.hidden = false; error.textContent = problem; clearResults(); return; }
    error.hidden = true; error.textContent = '';

    var horizon = years * 12, ret01 = ret / 100;
    var tot = { day: 0, month: 0, year: 0, interest: 0, grow: 0, months: 0 };
    var byDebt = clearBody('codByDebt');
    debts.forEach(function (d, i) {
      var c = costToday(d), p = plans[i], g = investedValue(p.charges, ret01, horizon);
      tot.day += c.day; tot.month += c.month; tot.year += c.year; tot.interest += p.interest; tot.grow += g;
      tot.months = Math.max(tot.months, p.months);
      var share = Math.min(c.month / d.pay, 1);
      addRow(byDebt, [d.name, money.format(d.balance), aprText(d.apr), money.format(c.day), money.format(c.year),
        Math.round(share * 100) + '%', dateAfter(p.months), money.format(p.interest), money.format(g)]);
    });
    set('codDay', money.format(tot.day));
    set('codMonth', money.format(tot.month));
    set('codYear', money.format(tot.year));
    set('codTotal', money.format(tot.interest));
    set('codDate', dateAfter(tot.months));
    set('codDateNote', 'Last debt cleared in ' + duration(tot.months) + ' at your current payments.');
    set('codGrow', money.format(tot.grow));
    set('codGrowNote', 'Every interest charge invested at ' + (Math.round(ret * 100) / 100) + '% a year and left to grow for ' + years + (years === 1 ? ' year.' : ' years.'));
    var hn = document.getElementById('codHorizonNote');
    hn.hidden = tot.months <= horizon;
    if (!hn.hidden) hn.textContent = 'Some debts run past ' + years + (years === 1 ? ' year' : ' years') + ', so only the interest charged within that time is counted in the invested value.';

    var yearsBody = clearBody('codYears');
    var lastYear = Math.ceil(Math.max(tot.months, horizon) / 12), cum = 0;
    var i01 = ret01 / 12, inv = 0;
    for (var y = 1; y <= lastYear; y++) {
      var yInt = 0, owed = 0;
      for (var m = (y - 1) * 12 + 1; m <= y * 12; m++) {
        var mInt = 0;
        plans.forEach(function (p) { if (m <= p.charges.length) mInt += p.charges[m - 1]; });
        yInt += mInt;
        inv = inv * (1 + i01) + mInt;
      }
      plans.forEach(function (p) { owed += y * 12 <= p.owed.length ? p.owed[y * 12 - 1] : 0; });
      cum += yInt;
      addRow(yearsBody, [String(y), money.format(yInt), money.format(cum), money.format(owed), money.format(inv)]);
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    DEFAULTS.forEach(addDebtRow);
    var form = document.getElementById('codForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    document.getElementById('codAdd').addEventListener('click', function () {
      if (document.getElementById('codDebts').querySelectorAll('[data-debt-row]').length >= MAX_DEBTS) return;
      addDebtRow({ name: '', balance: '', apr: '', pay: '' });
      update();
    });
    update();
  });
})();
